<?php
namespace App\Http\Controllers\tenant; use App\Enums\UserAccountStatus; use App\Enums\LeaveRequestStatus; use App\Http\Controllers\Controller; use App\Models\Attendance; use App\Models\AttendanceLog; use App\Models\User; use App\Models\Shift; use App\Models\Holiday; use App\Models\Team; use App\Models\Site; use App\Constants\Constants as AppConstants; use Carbon\Carbon; use Illuminate\Http\Request; use Illuminate\Support\Facades\Log; use Yajra\DataTables\Facades\DataTables; class AttendanceController extends Controller { public function index() { $currentUser = auth()->user(); $scopedIds = $this->getScopedUserIds($currentUser); $activeUsersCountQuery = User::where('status', UserAccountStatus::ACTIVE); if ($scopedIds) $activeUsersCountQuery->whereIn('id', $scopedIds); $activeUsersCount = $activeUsersCountQuery->count(); /* "Present" must mean the same thing on the card as in the weekly chart
       below, which counts present + late + WFH. The card used to count only
       status='present', so the two halves of this page disagreed. Deduplicated
       per user so multiple check-ins in a day count once. */
    /* Today's header cards - tallied through the same AttendanceDayStatus resolver as every other attendance surface, instead of matching raw status text. That raw match counted an uncorrected miss-punch as Present (its raw status defaults to 'Present' with no check-out recorded) and never recognised a worked designated off-Saturday/holiday as Present at all, since its raw status never says 'present'. */ $todayRowsQuery = Attendance::whereDate('check_in_time', today())->with(['user', 'leaveRequest.leaveType']); if ($scopedIds) $todayRowsQuery->whereIn('user_id', $scopedIds); $todayRowsByUser = $todayRowsQuery->get()->groupBy('user_id'); $todayPresentCount = 0; $todayAbsentCount = 0; $lateCount = 0; foreach ($todayRowsByUser as $userRows) { $best = $userRows->sortByDesc(function($a) { return ($a->check_in_time && $a->check_in_time->format('H:i') !== '00:00') ? 1 : 0; })->first(); $holiday = $best->check_in_time ? \App\Services\AttendanceDayStatus::holidayForUserOnDateSingle($best->user, $best->check_in_time->toDateString()) : null; $code = \App\Services\AttendanceDayStatus::resolve($best->user, $best->check_in_time ?? Carbon::today(), $best, null, $holiday)['code']; if (in_array($code, \App\Services\AttendanceDayStatus::PRESENT_LIKE_CODES, true)) { $todayPresentCount++; } elseif (in_array($code, ['absent', 'miss-punch'], true)) { $todayAbsentCount++; } if ($code === 'late') { $lateCount++; } } $onLeaveCountQuery = \App\Models\LeaveRequest::where('status', \App\Enums\LeaveRequestStatus::APPROVED) ->whereDate('from_date', '<=', today()) ->whereDate('to_date', '>=', today()); if ($scopedIds) $onLeaveCountQuery->whereIn('user_id', $scopedIds); $onLeaveCount = $onLeaveCountQuery->count(); $usersQuery = User::whereIn('status', [UserAccountStatus::ACTIVE, UserAccountStatus::ONBOARDING_SUBMITTED, UserAccountStatus::TERMINATED]); if ($scopedIds) $usersQuery->whereIn('id', $scopedIds); $users = $usersQuery->get(); $shifts = Shift::get(); $teams = Team::get(); return view('tenant.attendance.index', [ 'pageConfigs' => ['contentLayout' => 'wide'], 'users' => $users, 'shifts' => $shifts, 'teams' => $teams, 'todayPresentCount' => $todayPresentCount, 'todayAbsentCount' => $todayAbsentCount, 'onLeaveCount' => $onLeaveCount, 'lateCount' => $lateCount, 'activeUsersCount' => $activeUsersCount, 'sites' => Site::all(), /* The "Dept" filter used to list `teams` — 5 leftover demo rows ("Demo Team", "Testq") that only 3 users are attached to, so the dropdown looked empty and filtering by it returned nothing. Departments are the real organisational grouping (30 rows, ~232 users), and registryAjax already honoured a `departmentId` param. */ 'departments' => \App\Models\Department::orderBy('name')->get() ]); } private function getScopedUserIds($user) { if ($user->hasRole(['admin', 'hr', 'accounts'])) { return null; } if ($user->hasRole('manager')) { $ids = User::where('reporting_to_id', $user->id)->notTerminated()->pluck('id')->toArray(); $ids[] = $user->id; return $ids; } return [$user->id]; } public function indexAjax(Request $request) { $currentUser = auth()->user(); $scopedIds = $this->getScopedUserIds($currentUser); $query = Attendance::query() ->with(['attendanceLogs', 'user', 'shift', 'updatedBy', 'leaveRequest.leaveType']); if ($scopedIds) { $query->whereIn('user_id', $scopedIds); } if ($request->has('userId') && $request->input('userId')) { $query->where('user_id', $request->input('userId')); } if ($request->has('shiftId') && $request->shiftId) { $query->where('shift_id', $request->shiftId); } if ($request->has('siteId') && $request->siteId) { $query->whereHas('user', function($q) use ($request) { $q->where('site_id', $request->siteId); }); } $query->orderBy('check_in_time', 'desc'); if ($request->has('teamId') && $request->input('teamId')) { $query->whereHas('user', function($q) use ($request) { $q->where('team_id', $request->input('teamId')); }); } if ($request->has('departmentId') && $request->input('departmentId')) { $query->whereHas('user', function($q) use ($request) { $q->where('department_id', $request->input('departmentId')); }); } if ($request->has('startDate') && $request->input('startDate') && $request->has('endDate') && $request->input('endDate')) { $startDate = Carbon::parse($request->input('startDate'))->startOfDay(); $endDate = Carbon::parse($request->input('endDate'))->endOfDay(); $query->whereBetween('check_in_time', [$startDate, $endDate]); } elseif ($request->has('date') && $request->input('date')) { try { $date = Carbon::parse($request->input('date'))->toDateString(); $query->whereDate('check_in_time', $date); } catch (\Exception $e) { $query->whereDate('check_in_time', Carbon::today()); } } else { $query->whereDate('check_in_time', Carbon::today()); } if ($request->has('searchTerm') && $request->input('searchTerm')) { $searchTerm = $request->input('searchTerm'); $query->whereHas('user', function($q) use ($searchTerm) { $q->where('first_name', 'like', "%{$searchTerm}%") ->orWhere('last_name', 'like', "%{$searchTerm}%") ->orWhere('code', 'like', "%{$searchTerm}%"); }); } return DataTables::of($query) ->addIndexColumn() ->addColumn('date', function ($attendance) { return $attendance->check_in_time ? $attendance->check_in_time->format('d/m/Y') : 'N/A'; }) ->editColumn('check_in_time', function ($attendance) { return $attendance->check_in_time ? $attendance->check_in_time->format('H:i') : '--:--'; }) ->editColumn('check_out_time', function ($attendance) { return $attendance->check_out_time ? $attendance->check_out_time->format('H:i') : '--:--'; }) ->addColumn('shift', function ($attendance) { return $attendance->shift ? '<span class="badge bg-label-teal px-3 py-1 rounded-pill fw-bold" style="font-size:0.65rem;">'.e($attendance->shift->name).'</span>' : '<span class="text-muted">N/A</span>'; }) ->addColumn('working_hours', function ($attendance) { if ($attendance->check_in_time && $attendance->check_out_time) { $diff = $attendance->check_in_time->diff($attendance->check_out_time); return '<span class="fw-black text-teal">'.sprintf('%d:%02dh', $diff->h, $diff->i).'</span>'; } return '<span class="fw-bold text-muted">0:00h</span>'; }) ->addColumn('status', function ($attendance) { $holiday = $attendance->check_in_time ? \App\Services\AttendanceDayStatus::holidayForUserOnDateSingle($attendance->user, $attendance->check_in_time->toDateString()) : null; $r = \App\Services\AttendanceDayStatus::resolve($attendance->user, $attendance->check_in_time ?: Carbon::today(), $attendance, null, $holiday); $isPaid = $r['isPaid']; $leaveDetail = ''; if ($attendance->leaveRequest) { if ($attendance->leaveRequest->is_short_leave) { $leaveDetail = ' (Short Leave)'; } elseif ($attendance->leaveRequest->is_half_day) { $session = $attendance->leaveRequest->half_day_session === 'second_half' ? '2nd Half' : '1st Half'; $leaveDetail = ' (Half Day - ' . $session . ')'; } } $color = 'bg-teal'; $icon = 'bx-check-circle'; $s = $r['code']; if($s == 'sp') { $color = 'bg-success'; $icon = 'bx-calendar-check'; $status = 'SP'; } elseif($s == 'hp') { $color = 'bg-success'; $icon = 'bx-calendar-check'; $status = 'HP'; } elseif($s == 'absent') { $color = 'bg-red'; $icon = 'bx-x-circle'; $status = 'Absent'; } elseif($s == 'miss-punch') { $color = 'bg-miss-punch'; $icon = 'bx-error-circle'; $status = 'Miss Punch'; } elseif($s == 'half-day') { $color = 'bg-orange'; $icon = 'bx-time'; $status = 'Half-Day' . $leaveDetail; } elseif($s == 'half-day-paid') { $color = 'bg-indigo-gradient'; $icon = 'bx-check-circle'; $status = 'Present' . $leaveDetail . ' (Paid)'; } elseif($s == 'late') { $color = 'bg-warning'; $icon = 'bx-time'; $status = 'Late'; } elseif($s == 'paid_leave' || $s == 'leave') { $color = 'bg-indigo-vibrant'; $icon = 'bx-calendar-check'; $status = 'Paid Leave' . $leaveDetail; } elseif($s == 'unpaid_leave' || $s == 'on_leave') { $color = 'bg-purple-vibrant'; $icon = 'bx-calendar-x'; $status = 'Unpaid Leave' . $leaveDetail; } elseif($s == 'work_from_home' || $s == 'wfh') { $color = 'bg-wfh'; $icon = 'bx-home'; $status = 'WFH'; } else { $status = 'Present' . $leaveDetail; } $editBadge = ''; if ($attendance->admin_reason) { $editBadge = '<i class="bx bxs-edit-alt ms-1 text-white opacity-75" title="Manual Adjustment"></i>'; } $shortLeaveIcon = ''; if ($attendance->leave_request_id) { $shortLeaveIcon = ' <i class="bx bxs-time-five ms-1 text-white opacity-75" title="Short Leave Applied"></i>'; } return '<span class="badge '.$color.' border-0 px-3 py-2 rounded-2 fw-black text-uppercase ls-1 text-white shadow-sm" style="font-size:0.65rem; min-width:80px;"><i class="bx '.$icon.' me-1"></i>'.$status.$editBadge.$shortLeaveIcon.'</span>'; }) ->addColumn('actions', function ($attendance) { $editorData = ''; if ($attendance->admin_reason) { $editorName = e($attendance->updatedBy?->getFullName() ?? 'Admin'); $reason = e($attendance->admin_reason); $editorData = 'data-editor="' . $editorName . '" data-reason="' . $reason . '"'; } $actions = '<div class="d-flex align-items-center gap-2">'. '<button class="btn btn-sm btn-icon hitech-action-icon" onclick="viewLogs('.$attendance->id.')" title="View Logs"><i class="bx bx-list-ul"></i></button>'; if (auth()->user()->hasRole(['admin', 'hr', 'accounts'])) { $actions .= '<button class="btn btn-sm btn-icon hitech-action-icon" onclick="editRecord('.$attendance->id.')" title="Edit" '.$editorData.'><i class="bx bx-edit"></i></button>'; } $actions .= '</div>'; return $actions; }) ->addColumn('user', function ($attendance) { $name = $attendance->user ? (string) $attendance->user->getFullName() : 'Unknown'; $code = $attendance->user ? (string) $attendance->user->code : '--'; $initials = $attendance->user?->getInitials() ?? 'NA'; $clickAction = 'onclick="showEmployeeSummary(' . e(json_encode($name)) . ', ' . e(json_encode($code)) . ', 0, 0, 0, 0, \'Current Filter\')"'; $profileUrl = $attendance->user?->getProfilePicture(); if ($profileUrl) { $profileOutput = '<img src="' . e($profileUrl) . '"  alt="Avatar" class="avatar rounded-circle " />'; } else { $profileOutput = '<span class="avatar-initial rounded-circle bg-label-teal fw-black">' . e($initials) . '</span>'; } return '<div class="d-flex justify-content-start align-items-center user-name cursor-pointer" '.$clickAction.'>' . '<div class="avatar-wrapper">' . '<div class="avatar avatar-md me-3 shadow-sm">' . $profileOutput . '</div>' . '</div>' . '<div class="d-flex flex-column">' . '<span class="text-teal text-truncate fw-black hover-teal" style="font-size: 0.85rem; text-decoration: underline dotted;">' . e($attendance->user?->getFullName()) . '</span>' . '<small class="text-muted fw-bold" style="font-size: 0.7rem;">' . e($attendance->user?->code) . '</small>' . '</div>' . '</div>'; }) ->rawColumns(['user', 'status', 'actions', 'shift', 'working_hours', 'check_in_time', 'check_out_time']) ->with('stats', function() use ($query) { /* Tallied through the same AttendanceDayStatus resolver as the row-level status column above, instead of a separate raw-SQL approximation - a plain 465-minute cutoff with no Sunday/holiday/leave awareness used to let these header counts silently disagree with the badges in the rows beneath them. present/absent/leave/late is a coarser bucket set than the resolver's own codes, so codes are grouped by what they visually read as on the card: sp/hp/wfh/half-day-paid alongside present (the employee was accounted for that day); half-day/miss-punch alongside late (showed up, but something needs correcting); every leave/holiday/weekly-off variant together as leave (not expected to be a plain working day). */ $rows = (clone $query)->reorder()->get(); $totalCount = max($rows->count(), 1); $presentCount = 0; $absentCount = 0; $leaveCount = 0; $lateCount = 0; foreach ($rows as $row) { $holiday = $row->check_in_time ? \App\Services\AttendanceDayStatus::holidayForUserOnDateSingle($row->user, $row->check_in_time->toDateString()) : null; $rr = \App\Services\AttendanceDayStatus::resolve($row->user, $row->check_in_time ?: Carbon::today(), $row, null, $holiday); switch ($rr['code']) { case 'present': case 'short-leave-present': case 'sp': case 'hp': case 'work_from_home': case 'wfh': case 'half-day-paid': $presentCount++; break; case 'absent': $absentCount++; break; case 'late': case 'half-day': case 'miss-punch': $lateCount++; break; default: $leaveCount++; break; } } return [ 'present' => $presentCount, 'absent' => $absentCount, 'leave' => $leaveCount, 'late' => $lateCount, 'presentPercentage' => round(($presentCount / $totalCount) * 100) ]; })->make(true); } public function registryAjax(Request $request) { $month = $request->input('month', now()->month); $year = $request->input('year', now()->year); $startOfMonth = Carbon::create($year, $month, 1)->startOfMonth(); $endOfMonth = $startOfMonth->copy()->endOfMonth(); $daysInMonth = $startOfMonth->daysInMonth; $currentUser = auth()->user(); $scopedIds = $this->getScopedUserIds($currentUser); $usersQ = User::where(function($q) use ($startOfMonth) { $q->whereIn('status', [UserAccountStatus::ACTIVE, UserAccountStatus::ONBOARDING_SUBMITTED])->orWhere(function($q2) use ($startOfMonth) { $q2->where('status', UserAccountStatus::TERMINATED)->where(function($q3) use ($startOfMonth) { $q3->whereDate('last_working_day', '>=', $startOfMonth)->orWhere(function($q4) use ($startOfMonth) { $q4->whereNull('last_working_day')->whereDate('exit_date', '>=', $startOfMonth); }); }); }); }); if ($scopedIds) { $usersQ->whereIn('id', $scopedIds); } if ($request->userId) $usersQ->where('id', $request->userId); if ($request->shiftId) $usersQ->where('shift_id', $request->shiftId); if ($request->teamId) $usersQ->where('team_id', $request->teamId); if ($request->departmentId) $usersQ->where('department_id', $request->departmentId); if ($request->siteId) $usersQ->where('site_id', $request->siteId); if ($request->searchTerm) { $term = $request->searchTerm; $usersQ->where(function($q) use ($term) { $q->where('first_name', 'like', "%$term%") ->orWhere('last_name', 'like', "%$term%") ->orWhere('code', 'like', "%$term%"); }); } $users = $usersQ->with([ 'shift', 'leavePolicyProfile.rules', 'site', 'department', 'attendance' => function($q) use ($month, $year) { $q->whereMonth('check_in_time', $month) ->whereYear('check_in_time', $year) ->with(['updatedBy', 'leaveRequest.leaveType']); }, 'leaveRequests' => function($q) use ($startOfMonth, $endOfMonth) { $q->where('status', LeaveRequestStatus::APPROVED) ->where(function($q2) use ($startOfMonth, $endOfMonth) { $q2->whereBetween('from_date', [$startOfMonth, $endOfMonth]) ->orWhereBetween('to_date', [$startOfMonth, $endOfMonth]); })->with('leaveType'); } ])->get(); foreach ($users as $u) { try { \App\Services\AttendanceAdjustmentService::autoOffsetSundayWorking($u, $month, $year); } catch (\Exception $e) { \Log::error("Failed to run auto-offset for user " . $u->id . ": " . $e->getMessage()); } } $users->load([ 'attendance' => function($q) use ($month, $year) { $q->whereMonth('check_in_time', $month) ->whereYear('check_in_time', $year) ->with(['updatedBy', 'leaveRequest.leaveType']); }, 'leaveRequests' => function($q) use ($startOfMonth, $endOfMonth) { $q->where('status', LeaveRequestStatus::APPROVED) ->where(function($q2) use ($startOfMonth, $endOfMonth) { $q2->whereBetween('from_date', [$startOfMonth, $endOfMonth]) ->orWhereBetween('to_date', [$startOfMonth, $endOfMonth]); })->with('leaveType'); } ]); /* Single source of truth for the day-status decision, shared with the admin Attendance Logs page and the employee's own My Attendance calendar/list - see AttendanceDayStatus for why. */ $holidayMaps = \App\Services\AttendanceDayStatus::holidayMapsForMonth($month, $year); $data = []; foreach ($users as $user) { $row = [ 'employee' => $user->getFullName(), 'code' => $user->code, 'department' => optional($user->department)->name, 'biometric_id' => $user->biometric_id, 'presents' => 0.0, 'absents' => 0.0, 'lates' => 0, 'leaves' => 0, 'npl' => 0.0, 'offs' => 0 ]; for ($day = 1; $day <= $daysInMonth; $day++) { $dateObj = Carbon::create($year, $month, $day); $dateStr = $dateObj->toDateString(); $holiday = \App\Services\AttendanceDayStatus::holidayForUserOnDate($holidayMaps, $user, $user->site_id, $dateStr); $partDayLabel = ($holiday && $holiday->isPartDay()) ? $holiday->type_label : null; $attendance = $user->attendance->filter(function($a) use ($dateStr) { return $a->check_in_time->toDateString() == $dateStr; })->sortByDesc(function($a) { $isDummy = $a->check_in_time && $a->check_in_time->format('H:i') === '00:00'; return $isDummy ? 0 : 1; })->first(); $dayData = [ 'status' => 'Missing', 'in' => '--', 'out' => '--', 'hours' => '--', 'class' => 'bg-light text-muted opacity-50', 'user_id' => $user->id, 'full_date' => $dateStr ]; $matchingLeave = $user->leaveRequests->first(function($l) use ($dateStr) { return Carbon::parse($l->from_date)->toDateString() <= $dateStr && Carbon::parse($l->to_date)->toDateString() >= $dateStr; }); $r = \App\Services\AttendanceDayStatus::resolve($user, $dateObj, $attendance, $matchingLeave, $holiday); if ($attendance) { $dayData['id'] = $attendance->id; $dayData['in'] = $attendance->check_in_time ? $attendance->check_in_time->format('H:i') : '--'; $dayData['out'] = $attendance->check_out_time ? $attendance->check_out_time->format('H:i') : '--'; if ($attendance->check_in_time && $attendance->check_out_time) { $diff = $attendance->check_in_time->diff($attendance->check_out_time); $dayData['hours'] = sprintf('%d:%02dh', $diff->h, $diff->i); } else { $dayData['hours'] = '0:00h'; } $dayData['is_edited'] = !empty($attendance->admin_reason); $dayData['editor_name'] = $attendance->updatedBy?->getFullName() ?? 'Admin'; $dayData['admin_reason'] = $attendance->admin_reason; $dayData['attachment'] = $attendance->attachment ? asset('storage/' . $attendance->attachment) : null; $dayData['is_short_leave'] = $attendance->leaveRequest?->leaveType?->is_short_leave ?? false; if ($partDayLabel) { $dayData['part_day'] = $partDayLabel; } } switch ($r['code']) { case 'present': $dayData['status'] = 'Present'; $dayData['class'] = 'bg-teal text-white'; $row['presents'] += 1; if ($partDayLabel) { $dayData['status'] = 'Present*'; $dayData['part_day'] = $partDayLabel; } break; case 'short-leave-present': $dayData['status'] = 'Present'; $dayData['class'] = 'bg-short-leave text-white'; $row['presents'] += 1; break; case 'miss-punch': $dayData['status'] = 'Miss Punch'; $dayData['hours'] = 'MP'; $dayData['class'] = 'bg-miss-punch text-white'; $row['absents'] += 1; break; case 'sp': $dayData['status'] = 'SP'; $dayData['class'] = 'bg-success text-white'; $row['presents'] += 1; break; case 'hp': $dayData['status'] = 'HP'; $dayData['class'] = 'bg-success text-white'; $row['presents'] += 1; break; case 'weekly_off': $dayData['status'] = 'OFF'; $dayData['hours'] = 'OFF'; $dayData['class'] = 'bg-secondary bg-opacity-10 text-muted'; $row['offs']++; break; case 'holiday': $dayData['status'] = 'Holiday'; $dayData['in'] = $r['holidayName'] ?? 'Holiday'; $dayData['out'] = '--'; $dayData['hours'] = 'HOL'; $dayData['class'] = 'bg-info bg-opacity-25 text-info border-info border-opacity-50'; $row['offs']++; break; case 'late': $dayData['status'] = 'Late'; $dayData['class'] = 'bg-warning text-white'; $row['presents'] += 1; $row['lates'] += 1; break; case 'half-day-paid': $dayData['status'] = 'Half Day'; $dayData['class'] = 'bg-indigo-gradient text-white'; $dayData['hours'] .= ' (HD-PL)'; $row['presents'] += 0.5; $row['leaves'] += 0.5; break; case 'half-day': $dayData['status'] = 'Half Day'; $dayData['class'] = 'bg-orange text-white'; $row['presents'] += 0.5; $row['absents'] += 0.5; break; case 'absent': $dayData['status'] = 'Absent'; $dayData['class'] = 'bg-red text-white'; $row['absents'] += 1; if (!$attendance) { $dayData['in'] = 'No Log'; $dayData['out'] = '--'; $dayData['hours'] = '--'; } break; case 'paid_leave': case 'leave': $dayData['status'] = 'Paid Leave'; $dayData['class'] = 'bg-indigo-vibrant text-white'; $dayData['hours'] = 'PL'; $row['leaves'] += 1; if (!$attendance) { $dayData['in'] = 'Paid Leave'; $dayData['out'] = '--'; if ($r['isHalfDay']) { $row['presents'] += 1; } } break; case 'unpaid_leave': case 'on_leave': $dayData['status'] = 'Unpaid Leave'; $dayData['class'] = 'bg-purple-vibrant text-white'; $dayData['hours'] = 'NPL'; $row['npl'] += 1; if (!$attendance) { $dayData['in'] = 'Non Paid Leave'; $dayData['out'] = '--'; } break; case 'work_from_home': case 'wfh': $dayData['status'] = 'WFH'; $dayData['class'] = 'bg-wfh text-white'; $row['presents'] += 1; break; case 'scheduled': $dayData['status'] = 'Scheduled'; $dayData['in'] = 'Upcoming'; $dayData['out'] = '--'; $dayData['hours'] = '--'; $dayData['class'] = 'bg-white border text-muted opacity-50'; break; case 'today': $dayData['status'] = 'Today'; $dayData['in'] = 'Today'; $dayData['out'] = '--'; $dayData['hours'] = '--'; $dayData['class'] = 'bg-white border-primary border-dashed text-primary'; break; } $row['day_'.$day] = $dayData; } $row['payable'] = $row['presents'] + $row['offs'] + $row['leaves']; $data[] = $row; } return response()->json([ 'daysInMonth' => $daysInMonth, 'data' => $data, 'month' => (int)$month, 'year' => (int)$year ]); } public function chartAjax(Request $request) { $period = $request->input('period', '7days'); $departmentId = $request->input('departmentId') ?: $request->input('teamId'); $userId = $request->input('userId'); $endDate = Carbon::now(); $startDate = Carbon::now(); if ($period == 'today') { $startDate = Carbon::now()->startOfDay(); } elseif ($period == 'yesterday') { $startDate = Carbon::now()->subtract(1, 'days')->startOfDay(); $endDate = Carbon::now()->subtract(1, 'days')->endOfDay(); } elseif ($period == '7days') { $startDate = Carbon::now()->subtract(6, 'days')->startOfDay(); } elseif ($period == '1month') { $startDate = Carbon::now()->subtract(30, 'days')->startOfDay(); } elseif ($period == '3months') { $startDate = Carbon::now()->subtract(3, 'months')->startOfDay(); } elseif ($period == '1year') {