 'like', "%{$term}%") ->orWhere('last_name', 'like', "%{$term}%") ->orWhere('code', 'like', "%{$term}%"); }); }) ->get(); /* Tallied through the same AttendanceDayStatus resolver as every other attendance surface (a raw status match here counted an uncorrected miss-punch as present, and never recognised a worked designated off-Saturday/holiday), and deduplicated per user per date - the raw COUNT(*) this replaced could double-count a user with more than one row on the same date, occasionally pushing the chart's percentage past 100%. */ $chartHolidayMapsByMonth = []; $attendancesByDate = []; foreach ($attendancesByDateRows->groupBy(fn($a) => $a->check_in_time->toDateString()) as $dateStr => $dayRows) { $count = 0; foreach ($dayRows->groupBy('user_id') as $userRows) { $best = $userRows->sortByDesc(fn($a) => ($a->check_in_time && $a->check_in_time->format('H:i') !== '00:00') ? 1 : 0)->first(); $d = $best->check_in_time; $monthKey = $d->year . '-' . $d->month; if (!isset($chartHolidayMapsByMonth[$monthKey])) { $chartHolidayMapsByMonth[$monthKey] = \App\Services\AttendanceDayStatus::holidayMapsForMonth($d->month, $d->year); } $holiday = \App\Services\AttendanceDayStatus::holidayForUserOnDate($chartHolidayMapsByMonth[$monthKey], $best->user, $best->user->site_id, $dateStr); if (\App\Services\AttendanceDayStatus::isPresentLikeRow($best, $holiday)) { $count++; } } $attendancesByDate[$dateStr] = $count; } $attendancesByDate = collect($attendancesByDate); for ($date = $startDate->copy(); $date->lte($endDate); $date->addDay()) { $dateStr = $date->toDateString(); $label = $period == 'today' ? $date->format('H:i') : $date->format('d M'); if ($period == '7days') $label = $date->format('D'); $categories[] = $label; $pCount = $attendancesByDate->get($dateStr, 0); $presentData[] = $pCount; $aCount = $totalStaff - $pCount; if ($aCount < 0) $aCount = 0; $absentData[] = $aCount; } return response()->json([ 'categories' => $categories, 'series' => [ ['name' => 'Present', 'data' => $presentData], ['name' => 'Absent', 'data' => $absentData] ] ]); } public function editAjax($id) { if (auth()->user()->hasRole('manager') && !auth()->user()->hasRole(['admin', 'hr', 'accounts'])) { return response()->json(['success' => false, 'message' => 'Unauthorized.'], 403); } $attendance = Attendance::with('user')->findOrFail($id); return response()->json([ 'success' => true, 'attendance' => $attendance, 'user' => $attendance->user->getFullName() ]); } public function updateAjax(Request $request, $id) { if (auth()->user()->hasRole('manager') && !auth()->user()->hasRole(['admin', 'hr', 'accounts'])) { return response()->json(['success' => false, 'message' => 'Managers are not authorized to edit attendance records.'], 403); } $attendance = Attendance::findOrFail($id); if ($request->status === 'present' && !$attendance->attachment && !$request->hasFile('attachment')) { return response()->json(['success' => false, 'message' => 'Proof of adjustment (attachment) is required when marking as Full Day.'], 422); } if (empty($request->admin_reason)) { return response()->json(['success' => false, 'message' => 'Adjustment reason is required.'], 422); } /* Nothing stopped a check-out earlier than the check-in, which produced impossible durations and left 10 corrupt rows in the data. */ if ($request->check_in_time && $request->check_out_time && $request->check_out_time <= $request->check_in_time) { return response()->json(['success' => false, 'message' => 'Check-out time must be later than check-in time.'], 422); } $data = [ 'status' => $request->status, 'admin_reason' => $request->admin_reason, 'updated_by_id' => auth()->id(), 'check_in_time' => $request->check_in_time ? \Carbon\Carbon::parse($attendance->check_in_time->format('Y-m-d') . ' ' . $request->check_in_time) : $attendance->check_in_time, 'check_out_time' => $request->check_out_time ? \Carbon\Carbon::parse($attendance->check_in_time->format('Y-m-d') . ' ' . $request->check_out_time) : $attendance->check_out_time, ]; if ($request->hasFile('attachment')) { $data['attachment'] = $request->file('attachment')->store('attendance/attachments', 'public'); } $attendance->update($data); return response()->json(['success' => true, 'message' => 'Attendance updated successfully.']); } public function storeAdjustmentAjax(Request $request) { if (auth()->user()->hasRole('manager') && !auth()->user()->hasRole(['admin', 'hr', 'accounts'])) { return response()->json(['success' => false, 'message' => 'Managers are not authorized to create attendance adjustments.'], 403); } if ($request->status === 'present' && !$request->hasFile('attachment')) { return response()->json(['success' => false, 'message' => 'Proof of adjustment (attachment) is required when marking as Full Day.'], 422); } if (empty($request->admin_reason)) { return response()->json(['success' => false, 'message' => 'Adjustment reason is required.'], 422); } $date = $request->date; $userId = $request->user_id; $checkIn = \Carbon\Carbon::parse($date . ' ' . ($request->check_in_time ?: '09:00')); $checkOut = \Carbon\Carbon::parse($date . ' ' . ($request->check_out_time ?: '18:00')); if ($checkOut->lte($checkIn)) { return response()->json(['success' => false, 'message' => 'Check-out time must be later than check-in time.'], 422); } $user = User::findOrFail($userId); $attendance = Attendance::create([ 'user_id' => $userId, 'shift_id' => $user->shift_id, 'check_in_time' => $checkIn, 'check_out_time' => $checkOut, 'status' => $request->status, 'admin_reason' => $request->admin_reason, 'updated_by_id' => auth()->id(), 'attachment' => $request->hasFile('attachment') ? $request->file('attachment')->store('attendance/attachments', 'public') : null ]); return response()->json(['success' => true, 'message' => 'Attendance created and adjusted successfully.']); } }